add_action( 'woocommerce_after_main_content', 'perfectpixel_content_below_shop_products', 5 );

function perfectpixel_content_below_shop_products() {
	if ( is_search() || ! ( is_shop() || ( 'yes' === '{{below_shop_everywhere}}' && is_product_taxonomy() ) ) ) {
		return;
	}
	echo '<div class="perfectpixel-below-shop" style="clear:both;margin-top:2em">' . wp_kses_post( do_shortcode( '{{below_shop_content}}' ) ) . '</div>';
}
